<script lang="ts">
 import appIcon from '../../design/app-icon.svg?url';
 import type { ProjectLink,ReleaseInfo,UpdateView } from './release';
 import {updateBusy,updateTitle} from './release';
 import {bytes} from './bridge';
 let {info,update,automatic=true,jobsActive=false,oncheck,ondownload,oninstall,onautomatic,onlink}:{info:ReleaseInfo;update:UpdateView;automatic?:boolean;jobsActive?:boolean;oncheck:()=>void;ondownload:()=>void;oninstall:()=>void;onautomatic:(value:boolean)=>void;onlink:(key:ProjectLink)=>void}=$props();
 const busy=$derived(updateBusy(update.stage));
 const downloading=$derived(update.stage==='downloading');
 const fraction=$derived(update.total&&update.total>0?Math.min(1,(update.downloaded||0)/update.total):undefined);
 function retry(){if(update.retry==='install')oninstall();else if(update.retry==='download')ondownload();else oncheck();}
</script>
<section class="about-panel" aria-label="About MaxRAR">
 <div class="identity"><img src={appIcon} alt=""/><h1>MaxRAR</h1><span>Version {info.version}</span><p>Understand, inspect, and extract archives.<br/>Built for Windows, macOS, and Linux.</p></div>
 <div class="updates" aria-label="Software updates">
  <div class="update-status" role="status"><span class="status-icon" class:spinning={busy} class:success={update.stage==='current'||update.stage==='ready'} aria-hidden="true">{busy?'':update.stage==='current'||update.stage==='ready'?'✓':update.stage==='error'?'!':'↓'}</span><strong>{updateTitle(update,info.unavailableReason)}</strong></div>
  {#if update.stage==='unavailable'}<p>{info.unavailableReason==='package_manager'?'Install the latest DEB or RPM package to update.':'Install the latest MaxRAR release to enable updates.'}</p>
  {:else if update.stage==='available'}<p>Your current version is {info.version}.</p>
  {:else if update.stage==='ready'}<p>{jobsActive?'Finish archive tasks before installing.':'Install when you’re ready to restart MaxRAR.'}</p>
  {:else if update.stage==='error'}<p>{update.retry==='download'?'The download could not be completed or verified.':update.retry==='install'?'The update could not be installed. Try again.':'Unable to check for updates. Try again later.'}</p>{/if}
  {#if downloading||update.stage==='verifying'}<div class="download"><progress aria-label="Update download progress" max="1" value={downloading?fraction:undefined}></progress>{#if downloading}<span>{fraction===undefined?bytes(update.downloaded||0):Math.round(fraction*100)+'%'}{update.total?' · '+bytes(update.total):''}</span>{/if}</div>{/if}
  {#if update.notes}<details class="release-notes"><summary>What’s new in {update.version}</summary><pre>{update.notes}</pre></details>{/if}
  <div class="update-actions">{#if update.stage==='unavailable'}<button class="secondary" onclick={()=>onlink('downloads')}>Download latest {info.unavailableReason==='package_manager'?'package':'version'} <span aria-hidden="true">↗</span></button>{:else if update.stage==='available'}<button class="primary" onclick={ondownload}>Download update</button>{:else if update.stage==='ready'}<button class="primary" disabled={jobsActive} onclick={oninstall}>Install &amp; restart</button>{:else if update.stage==='error'}<button class="secondary" disabled={update.retry==='install'&&jobsActive} onclick={retry}>Try again</button>{:else}<button class="secondary" disabled={busy} onclick={oncheck}>{busy?'Please wait…':'Check for updates'}</button>{/if}</div>
  {#if info.configured}<label class="auto-check"><input type="checkbox" checked={automatic} onchange={event=>onautomatic(event.currentTarget.checked)}/>Check automatically</label>{/if}
  {#if update.error}<details class="error-details"><summary>Update details</summary><pre>{update.error}</pre></details>{/if}
 </div>
 <div class="project-actions"><a href={info.links.repository} onclick={event=>{event.preventDefault();onlink('repository');}}>Star MaxRAR on GitHub <span aria-hidden="true">↗</span></a><a href={info.links.issues} onclick={event=>{event.preventDefault();onlink('issues');}}>Report an issue <span aria-hidden="true">↗</span></a></div>
 <footer><a href={info.links.organization} onclick={event=>{event.preventDefault();onlink('organization');}}>Matily</a></footer>
</section>
<style>
 .about-panel{font-size:13px;line-height:1.5;color:var(--text)}.identity{text-align:center;padding:4px 0 16px}.identity>img{width:56px;height:56px}.identity>h1{margin:8px 0 2px;font-size:28px;font-weight:650;letter-spacing:-.8px}.identity>span{font-size:12px;color:var(--muted)}.identity>p{margin:12px auto 0;font-size:13px;color:var(--muted);max-width:350px}.updates{border:1px solid var(--line);border-radius:7px;padding:12px;text-align:center;background:var(--soft2)}.update-status{display:flex;justify-content:center;align-items:center;gap:8px}.update-status>strong{font-size:13px;font-weight:550}.status-icon{display:grid;place-items:center;width:20px;height:20px;color:var(--muted);font-size:16px}.status-icon.success{color:#278143}.status-icon.spinning{border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:spin 1s linear infinite}.updates>p{font-size:12px;color:var(--muted);margin:8px 0 0}.update-actions{display:flex;justify-content:center;margin-top:10px}.about-panel button,.project-actions>a{font-size:13px;padding:8px 14px;min-height:36px;border-radius:6px}.secondary,.project-actions>a:first-child{background:var(--surface);border:1px solid var(--line)}.secondary:hover,.project-actions>a:first-child:hover{background:var(--soft)}.auto-check{display:flex;align-items:center;justify-content:center;gap:7px;margin-top:10px;font-size:11px;color:var(--muted)}.auto-check input{width:14px;height:14px;margin:0;accent-color:var(--accent)}.project-actions{display:flex;align-items:center;justify-content:center;gap:18px;padding:18px 0}.project-actions>a{text-decoration:none;color:var(--text);display:inline-flex;gap:6px;align-items:center}.project-actions>a>span{color:var(--muted);font-size:12px}.project-actions>a:last-child{color:var(--muted);padding-left:0;padding-right:0}footer{border-top:1px solid var(--line);padding:14px 0 0;text-align:center}footer>a{font-size:13px;font-weight:550;color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.download{margin:14px 0 0}.download progress{width:100%;height:8px;accent-color:var(--accent);border:0;border-radius:6px;overflow:hidden}.download progress::-webkit-progress-bar{background:var(--line)}.download progress::-webkit-progress-value{background:var(--accent);border-radius:6px}.download>span{display:block;color:var(--muted);font-size:11px;margin-top:5px}.release-notes,.error-details{text-align:left;margin-top:14px;font-size:12px}.release-notes summary,.error-details summary{cursor:pointer;color:var(--muted)}.release-notes pre,.error-details pre{font-size:11px;max-height:150px;overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:4px;padding:10px;line-height:1.5}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.status-icon.spinning{animation:none}}@media(max-width:440px){.project-actions{gap:8px;flex-wrap:wrap}.identity>p{font-size:12px}.project-actions>a{font-size:12px}.updates{padding:14px 12px}}
</style>
